(function(root){'use strict';const F=root.NutriFamily,E=root.NutriRegistrationEntry;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function reportHTML(p,updated=false){const r=p.report,labels={kcal:['热量','kcal'],protein:['蛋白质','g'],carb:['碳水','g'],fat:['脂肪','g'],grams:['份量','g']};return `<h2>成员当日日报</h2><p class="family-report-identity"><strong>${esc(p.name)}</strong> · ${esc(p.date)}</p><p class="family-report-label">合成数据 · 只读规则统计${updated?' · 已按最新资料更新':''}</p>${r.entryCount?`<p><strong>${r.slotCount} 类餐次 · ${r.entryCount} 条记录</strong></p><p class="family-report-slots">早餐 ${r.slots.breakfast} · 午餐 ${r.slots.lunch} · 晚餐 ${r.slots.dinner} · 加餐 ${r.slots.snack}${r.unknownSlot?' · 餐次未知 '+r.unknownSlot:''}</p><table class="family-report-table"><caption>已记录条目的已知小计</caption><thead><tr><th scope="col">项目</th><th scope="col">已知小计</th><th scope="col">已知 / 未知条目</th></tr></thead><tbody>${Object.entries(labels).map(([k,[label,unit]])=>{const n=r.nutrients[k];return `<tr><th scope="row">${label}</th><td>${n.value===null?'未知':esc(n.value)+' '+unit}</td><td>${n.known} / ${n.unknown}</td></tr>`;}).join('')}</tbody></table>`:'<p>这天暂无餐食记录；营养与份量未知。</p>'}<p class="family-report-note">仅汇总实际已填数值，不从菜名推算。未知不按 0 计算；小计不是全天总摄入，未记录不代表未进食。</p>`;}
async function mount(options=null){const embedded=!!options,page=options?.page||document.querySelector('#family-app'),S=E.store;let opened=false,returnFocus=null,returnContext=null,ready=false,unsubEntry=null;let state=null,active=true,busy=false,dirty=false,stale=false,unsub;const dirtyForms=new Set();
let view='members';
let statusTarget='[data-status-global]',dateStatusPrefix='';const guard=()=>active&&(!embedded||(opened&&options.parent.valid()));const status=(s,reveal=false)=>{const node=page.querySelector(statusTarget)||page.querySelector('[data-status-global]');node.textContent=(statusTarget==='[data-date-status]'?dateStatusPrefix:'')+s;if(reveal)node.scrollIntoView?.({block:'nearest',behavior:'smooth'});};
function dateLabel(value){const d=new Date(value+'T12:00:00Z');return value.replace(/-/g,' / ')+' · 周'+'日一二三四五六'[d.getUTCDay()];}
function avatar(member){return `<span class="family-avatar ${member.id==='self'?'is-self':''}" aria-hidden="true">${member.id==='self'?'我':'家'}</span>`;}
function contractHTML(){return `<section class="family-contract" aria-label="共享契约说明"><div class="family-contract-hero"><span class="family-contract-symbol" aria-hidden="true">◎</span><div><h2>本机家庭资料</h2><p>只在当前合成账号中查看成员记录；不是跨账号共享。</p></div></div><p class="family-notice">共享契约尚未实现 · 以下开关不可用，也不会保存共享草案或授予任何人访问权限。</p><div class="family-contract-options">${[['饮食记录','每日餐次、食物与已填营养'],['营养统计','只读汇总与已知 / 未知条目'],['饮食偏好','常吃食物与口味偏好'],['健康信息','身高体重与健康目标']].map(([title,help])=>`<div class="family-contract-row"><span><strong>${title}</strong><small>${help}</small></span><button type="button" class="family-switch" role="switch" aria-checked="false" aria-label="${title}共享未连接" data-unavailable disabled><span></span></button></div>`).join('')}</div><div class="family-contract-row family-card"><span><strong>共享给</strong><small>未建立受众与访问契约，不默认选择成员。</small></span><span class="family-tag">未接</span></div><button type="button" class="family-unavailable" data-unavailable disabled>撤回共享 · 未接</button><p class="family-fine">目前没有已生效的共享可撤回。归档成员仅保留本机成员数据，不等于撤回真实共享。</p><div class="family-contract-row family-card"><span><strong>云同步</strong><small>未连接；不会同步到其他账号或设备。</small></span><span class="family-tag">未接</span></div></section>`;}
function render(next){state=F.clone(next);stale=false;dirty=false;dirtyForms.clear();const f=state.health.family,p=f?F.projection(state):null;
const html=`<header class="family-page-header"><a href="intake.html" aria-label="返回营养摄入">‹</a><div><span class="family-eyebrow">LOCAL FAMILY · 合成演示</span><h1>家庭成员</h1></div><span class="family-local-badge">本机</span></header><p class="family-intro">一起记录，也保留每个人的边界。</p><p class="family-notice">请勿输入真实姓名或健康资料。仅本机合成演示，未接真实家庭服务。</p><p data-status-global role="status" aria-live="polite" aria-atomic="true"></p><div class="family-view-tabs" role="group" aria-label="家庭页面"><button type="button" data-view="members" aria-pressed="${view==='members'}">成员</button><button type="button" data-view="records" aria-pressed="${view==='records'}">当日记录</button><button type="button" data-view="contract" aria-pressed="${view==='contract'}">共享说明</button></div><div data-panel="members" ${view==='members'?'':'hidden'}><section class="family-members-section"><div class="family-section-heading"><h2>我的家庭</h2><span class="family-tag">${p?p.members.filter(m=>m.active).length:1} 位合成成员</span></div><p class="family-help">切换只改变家庭中的查看对象，不改变其他页面的本人记录。</p>${p?`<div class="family-members">${p.members.map(m=>`<article class="family-member-card ${m.id===p.memberId?'is-current':''} ${m.active?'':'is-archived'}"><div class="family-member-heading">${avatar(m)}<div class="family-member-copy"><strong>${esc(m.name)}</strong><small>${m.active?'合成示例 · 本机成员':'已归档 · 数据保留'}</small></div>${m.id===p.memberId?'<span class="family-tag is-blue">当前成员</span>':''}</div><div class="family-member-actions">${m.active?`<button type="button" data-action="select" data-id="${m.id}" ${m.id===p.memberId?'data-selected disabled':''}>${m.id===p.memberId?'当前查看':'查看记录'}</button><details class="family-edit"><summary>编辑资料</summary><form data-form="rename" data-id="${m.id}"><label>合成名称<input name="name" maxlength="40" required value="${esc(m.name)}" autocomplete="off"></label><div class="family-form-actions"><button>保存名称</button><button type="button" data-cancel-form class="family-secondary">取消</button></div><p data-local-status role="status" aria-live="polite" aria-atomic="true"></p></form></details>${m.id==='self'?'':`<button type="button" data-action="delete" data-id="${m.id}" class="family-text-button">归档</button>`}`:`<button type="button" data-action="restore" data-id="${m.id}">恢复成员</button>`}</div></article>`).join('')}</div><p data-members-status role="status" aria-live="polite" aria-atomic="true"></p>`:`<div class="family-empty"><span class="family-avatar is-self" aria-hidden="true">我</span><h3>从本人的合成记录开始</h3><p>首次启用保留当前本人资料快照，不修改原本人记录。</p><button type="button" data-action="init">启用合成家庭</button></div>`}</section>${p?`<section class="family-add-card"><details class="family-add"><summary><span class="family-plus" aria-hidden="true">＋</span><span><strong>添加家庭成员</strong><small>在本机创建空白合成成员</small></span><span aria-hidden="true">›</span></summary><form data-form="add"><label>演示名称<input name="name" maxlength="40" required placeholder="例如：合成家人 A" autocomplete="off"></label><div class="family-form-actions"><button>新增空白成员</button><button type="button" data-cancel-form class="family-secondary">取消</button></div><p data-local-status role="status" aria-live="polite" aria-atomic="true"></p></form><p class="family-fine">不会继承本人的餐食、指标、随访或提醒。</p></details></section>`:''}</div><div data-panel="records" ${view==='records'?'':'hidden'}>${p?`<section class="family-date-card"><div><span class="family-eyebrow">当前家庭视图</span><h2>${esc(p.name)}</h2><p>${esc(dateLabel(p.date))}</p></div><label>查看日期<input data-date type="date" value="${p.date}" aria-describedby="family-date-status"></label><p id="family-date-status" data-date-status role="status" aria-live="polite" aria-atomic="true"></p></section><section data-family-report class="family-card" aria-label="成员当日日报">${reportHTML(p)}</section><section class="family-card"><h2>这天的餐食</h2>${p.meals.length?`<ul class="family-meal-list">${p.meals.map(m=>`<li><time>${esc(m.time)}</time><span><strong>${esc(m.name)}</strong><small>${m.kcal===null||m.kcal===undefined?'热量未知':esc(m.kcal)+' kcal（合成）'}</small></span></li>`).join('')}</ul>`:'<p class="family-empty-note">暂无记录；未记录不代表未进食。</p>'}<details class="family-meal-editor"><summary>＋ 添加合成餐食</summary><form data-form="meal"><label>合成菜名<input name="name" required maxlength="40" placeholder="输入合成示例菜名"></label><div class="family-form-grid"><label>餐次<select name="slot"><option value="breakfast">早餐</option><option value="lunch">午餐</option><option value="dinner">晚餐</option><option value="snack">加餐</option></select></label><label>时间<input name="time" type="time" value="12:00" required></label></div><label class="family-consent"><input name="consent" type="checkbox" required><span>确认仅为合成数据，归属 ${esc(p.name)} / ${p.date}</span></label><p class="family-fine">份量与营养未知，不从菜名推算。</p><div class="family-form-actions"><button>确认记录</button><button type="button" data-cancel-form class="family-secondary">取消</button></div><p data-local-status role="status" aria-live="polite" aria-atomic="true"></p></form></details></section>`:'<section class="family-card family-empty"><h2>还未启用合成家庭</h2><p>请先在“成员”中启用，再按成员与日期查看记录。</p><button type="button" data-view="members">返回成员</button></section>'}</div><div data-panel="contract" ${view==='contract'?'':'hidden'}>${contractHTML()}</div><div class="family-refresh"><button type="button" data-refresh class="family-secondary">放弃未保存填写并刷新</button></div><footer><a href="settings.html">整个合成账号重置 / 回退说明 ›</a><p>归档保留成员数据；家庭资料随整个账号重置。账户撤销能力以共享入口显示为准。</p></footer>`;if(embedded)renderDrawer(html,p);else page.innerHTML=html;}
function renderDrawer(html,p){
 const hadFocus=page.contains(document.activeElement);page.innerHTML=options.original;
 page.querySelector('.family-title').textContent='我的家庭成员';
 const grid=page.querySelector('.family-grid');
 grid.innerHTML=p?p.members.filter(m=>m.active).map(m=>`<button type="button" class="family-cell ${m.id==='self'?'me':''} ${m.id===p.memberId?'active':''}" data-action="select" data-id="${esc(m.id)}" aria-pressed="${m.id===p.memberId}" ${m.id===p.memberId?'data-selected disabled':''}><span class="family-name">${esc(m.name)}</span><span class="family-sub">${m.id===p.memberId?'当前查看':'合成成员'}</span></button>`).join(''):'';
 const body=document.createElement('div');body.className='family-drawer-content';body.innerHTML=html;
 body.querySelector('header')?.remove();body.querySelector('nav')?.remove();body.querySelector('footer')?.remove();body.querySelector('.family-view-tabs')?.remove();body.querySelectorAll('[data-panel]').forEach(x=>x.hidden=false);body.querySelector('[data-panel="contract"]')?.remove();
 body.querySelectorAll('[data-action="select"]').forEach(x=>x.remove());
 const detail=document.createElement('details');detail.className='family-drawer-detail';detail.open=true;
 const summary=document.createElement('summary');summary.textContent='合成记录与管理';detail.append(summary,body);grid.after(detail);
 const footer=page.querySelector('.family-footer');footer.innerHTML='<p>本机合成演示；未接家庭服务、VIP或云同步。选择只影响本抽屉。</p><button type="button" data-drawer-close>关闭</button>';if(opened&&hadFocus)page.querySelector('[data-drawer-close]')?.focus({preventScroll:true});
}
function closeDrawer(restore=true,confirmed=false){if(!embedded||!opened)return true;if(busy||E.hasPending())return false;if(!confirmed&&!E.confirmLeave(dirty,'关闭家庭抽屉会放弃未保存填写，是否继续？'))return false;dirty=false;dirtyForms.clear();opened=false;document.body.classList.remove('family-drawer-pending');page.hidden=true;page.classList.remove('open');options.mask.hidden=true;options.handle.hidden=false;options.handle.setAttribute('aria-expanded','false');options.parent.block(false);const point=returnFocus,context=returnContext;returnFocus=null;returnContext=null;let sameIdentity=false;try{const now=F.context(S.read());sameIdentity=!!context&&Object.keys(context).filter(k=>k!=='revision').every(k=>context[k]===now[k]);}catch(_){}if(restore&&sameIdentity&&active&&options.parent.valid()&&point?.isConnected&&!point.disabled&&!point.hidden&&point.getClientRects().length)point.focus({preventScroll:true});return true;}
function openDrawer(){if(!embedded||!ready||!active||opened||busy||E.hasPending()||!options.parent.requestOpen())return false;try{render(S.read());}catch(e){E.report('家庭抽屉未就绪：'+e.message);return false;}opened=true;returnFocus=options.handle;returnContext=F.context(S.read());options.handle.hidden=true;options.handle.setAttribute('aria-expanded','true');page.hidden=false;page.classList.add('open');options.mask.hidden=false;options.parent.block(true);page.querySelector('[data-drawer-close]')?.focus({preventScroll:true});return true;}
function destroy(){active=false;opened=false;unsub?.();unsubEntry?.();if(embedded)document.body.classList.remove('family-drawer-pending');root.removeEventListener?.('beforeunload',beforeUnload);root.removeEventListener?.('pagehide',destroy);if(embedded){document.removeEventListener('click',outsideNavigation,true);options.parent.block(false);options.handle.remove();options.mask.remove();page.remove();}}
function beforeUnload(e){if(dirty){e.preventDefault();e.returnValue='';}}
function outsideNavigation(e){if(!opened||page.contains(e.target)||!e.target.closest?.('a[href]'))return;if(busy||E.hasPending()||!E.confirmLeave(dirty,'离开会放弃家庭抽屉未保存填写，是否继续？')){e.preventDefault();e.stopImmediatePropagation();}else closeDrawer(false,true);}

function disabled(v){page.querySelectorAll('button,input,select').forEach(x=>{if(x.hasAttribute('data-view'))x.disabled=busy||E.hasPending();else if(!x.hasAttribute('data-refresh'))x.disabled=v||stale||E.hasPending()||x.hasAttribute('data-unavailable')||x.hasAttribute('data-selected');});if(embedded){const close=page.querySelector('[data-drawer-close]');if(close)close.disabled=busy||E.hasPending();}}
async function execute(command){if(!guard()||busy||stale||E.hasPending()||!state)return;const base=F.clone(state);let planned;try{planned=F.candidate(base,command);}catch(e){status(e.message);return;}busy=true;disabled(true);if(command.type==='date')status('正在切换查看日期，尚未确认保存；下方日报仍以其标注的成员与日期为准。');const context=F.context(base);
try{await E.execute({kind:'family:'+command.type,context,input:planned.input,guard,
run:({input,context})=>S.transact(d=>{F.mutate(d,input);return null;},{context,expectedRevision:context.revision,guard,reason:'family:'+command.type}),
onSuccess:receipt=>{if(!active)return;try{const saved=F.verify(base,planned.state,receipt);if(!F.same(saved,S.read()))throw Error('已有更新版本，请刷新核对；不清空当前填写');render(saved);const region=page.querySelector(statusTarget);const disclosure=region?.closest?.('details');if(disclosure)disclosure.open=true;status(receipt.persistent?'已保存到本机合成账号。':'仅本页临时保存；刷新或离开即丢失。',true);}catch(e){stale=true;status(e.message);}},
onError:e=>{if(active)status(e.message+'；填写保留，请在共享入口核对原操作。');},
reconcile:({state:now})=>({status:F.same(now,base)?'base':'changed',message:'请核对当前记录；记录匹配不替代原操作回执。'})});}catch(e){if(active)status(e.message+'；填写保留。');}finally{busy=false;if(active)disabled(false);}}
page.addEventListener('input',e=>{if(embedded&&!opened)return;const form=e.target.closest?.('form');if(form?.dataset.form){dirty=true;dirtyForms.add(form);}});
page.addEventListener('submit',e=>{if(!guard())return;const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(!form.reportValidity()||busy||stale||E.hasPending())return;if([...dirtyForms].some(other=>other!==form)&&!E.confirmLeave(true,'此保存会关闭其他表单尚未保存的填写。是否放弃其他填写并继续？'))return;const type=form.dataset.form;statusTarget=type==='rename'?'[data-form="rename"][data-id="'+form.dataset.id+'"] [data-local-status]':'[data-form="'+type+'"] [data-local-status]';let c={type,name:form.elements.name.value};if(type==='rename')c.memberId=form.dataset.id;if(type==='meal'){if(!form.elements.consent.checked)return;const id=root.crypto?.randomUUID?.();if(!id){status('安全标识不可用，未保存。');return;}c={type,row:{id:'family-'+id,accountId:'demo-shen',memberId:state.health.family.selected,date:state.health.family.date,synthetic:true,name:c.name,time:form.elements.time.value,slot:form.elements.slot.value,kcal:null,carb:null,protein:null,fat:null,grams:null,source:'user-demo-entry'}};}void execute(c);});
page.addEventListener('click',e=>{if(!guard()||(embedded&&E.hasPending()))return;if(embedded&&e.target.closest('[data-drawer-close]')){closeDrawer();return;}const link=e.target.closest('a[href]');if(link){if(!E.confirmLeave(dirty,'离开将放弃未保存填写，是否继续？'))e.preventDefault();return;}const b=e.target.closest('button');if(!b)return;if(b.dataset?.view){if(busy||E.hasPending())return;view=b.dataset.view;page.querySelectorAll('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==view);page.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.view===view)));return;}if(b.dataset&&b.hasAttribute('data-cancel-form')){if(busy||E.hasPending())return;const form=b.closest('form');if(!form)return;if(dirtyForms.has(form)&&!E.confirmLeave(true,'取消会放弃此表单未保存的填写，是否继续？'))return;form.querySelectorAll('input,select').forEach(x=>{if(x.getAttribute('type')==='checkbox')x.checked=x.hasAttribute('checked');else if(x.tagName==='SELECT')x.value=x.querySelector('option')?.getAttribute('value')||'';else x.value=x.getAttribute('value')||'';});dirtyForms.delete(form);dirty=dirtyForms.size>0;const local=form.querySelector('[data-local-status]');if(local)local.textContent='已取消填写，未保存任何更改。';const disclosure=form.closest('details');if(disclosure)disclosure.open=false;return;}if(b.hasAttribute('data-refresh')){if(busy||!E.confirmLeave(dirty,'刷新会放弃未保存填写。'))return;try{render(S.read());}catch(err){status(err.message);}return;}const type=b.dataset.action;if(!type||busy||stale||E.hasPending())return;if(!E.confirmLeave(dirty,'此操作将放弃未保存填写。'))return;if(type==='delete'&&!root.confirm('归档该合成成员？记录保留，可恢复。'))return;statusTarget=type==='init'?'[data-status-global]':'[data-members-status]';void execute({type,memberId:b.dataset.id});});
page.addEventListener('change',e=>{if(!guard())return;if(!e.target.hasAttribute('data-date')||!state)return;const dateStatus=page.querySelector('[data-date-status]');if(busy||stale||E.hasPending()){if(dateStatus)dateStatus.textContent=stale?'资料已更新，日期选择保留但尚未提交；日报以其最新标注的成员与日期为准。请明确刷新后再操作。':'操作尚未确认，暂不能再次切换日期；当前输入保留，不代表已保存。请先在共享入口核对原操作，日报以其标注为准。';return;}if(dirty&&!E.confirmLeave(true,'切换日期会放弃未保存填写。')){e.target.value=state.health.family.date;if(dateStatus)dateStatus.textContent='已取消切换日期；仍查看 '+state.health.family.date+'，各表单未保存填写已保留。';return;}statusTarget='[data-date-status]';dateStatusPrefix='日期查看（'+F.projection(state).name+' / '+(e.target.value||'未选择日期')+'）：';void execute({type:'date',date:e.target.value});});
root.addEventListener('beforeunload',beforeUnload);root.addEventListener('pagehide',destroy);
if(embedded){unsubEntry=E.subscribe?.(()=>{document.body.classList.toggle('family-drawer-pending',opened&&E.hasPending());if(opened&&!busy)disabled(false);});options.handle.addEventListener('click',openDrawer);options.mask.addEventListener('click',()=>closeDrawer());page.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeDrawer();}});document.addEventListener('click',outsideNavigation,true);}

page.textContent='请先在共享入口确认合成演示…';try{await S.initialize({domains:['health'],guard:()=>active&&(!embedded||options.parent.valid())});if(!active)return;render(S.read());ready=true;unsub=S.subscribe(next=>{if(!active||busy||F.same(next,state))return;if(embedded&&!opened)return;stale=true;const report=page.querySelector('[data-family-report]');if(report){try{report.innerHTML=next.health.family?reportHTML(F.projection(next),true):'<p>家庭资料已重置，请刷新后查看。</p>';}catch(e){report.textContent='日报暂不可用，请刷新核对账号与成员。';}}const message='资料已从其他页面更新，日报已核对最新资料；其他显示与填写保留，请明确刷新后再操作。';const globalStatus=page.querySelector('[data-status-global]');if(globalStatus)globalStatus.textContent=message;const dateStatus=page.querySelector('[data-date-status]');if(dateStatus)dateStatus.textContent='资料已更新，日期控件保留原选择；日报已按最新成员与日期更新，以日报标注为准。暂不能切换，请明确刷新后再操作；确认刷新会放弃草稿。';page.querySelectorAll('[data-local-status]').forEach(node=>{node.textContent='资料已更新，此表单的填写已保留但尚未保存，暂不能提交。请核对最新成员与日期，再用页面底部刷新按钮继续；确认刷新会放弃草稿。';});disabled(true);});}catch(e){page.textContent='家庭入口未就绪：'+e.message+'。请重新加载后通过共享入口恢复，不会另建账号。';}
if(embedded){options.handle.disabled=!ready;if(!ready){options.handle.title='家庭抽屉未就绪，请重新加载并核对共享入口';E.report('家庭抽屉未就绪，未启用任何家庭写入；请重新加载并核对共享入口。');}}return {destroy};
}
function attach(parent){
 const source=document.querySelector('#source-template')?.content;if(!source)throw Error('原家庭抽屉模板缺失');
 const originalHandle=source.querySelector('.family-handle'),mask=source.querySelector('.family-mask').cloneNode(true),page=source.querySelector('.family-drawer').cloneNode(true);
 const handle=document.createElement('button');handle.type='button';handle.className=originalHandle.className;handle.innerHTML=originalHandle.innerHTML;handle.setAttribute('aria-expanded','false');handle.setAttribute('aria-controls','family-original-drawer');handle.disabled=true;
 mask.removeAttribute('data-wx-if');mask.removeAttribute('data-tap');mask.hidden=true;page.className='family-drawer family-embedded';page.id='family-original-drawer';page.hidden=true;page.setAttribute('role','dialog');page.setAttribute('aria-label','合成家庭成员与记录');
 const options={parent,handle,mask,page,original:page.innerHTML};document.body.append(handle,mask,page);let controller,retired=false;void mount(options).then(c=>{controller=c;if(retired)c?.destroy();});return {destroy(){retired=true;controller?.destroy();if(!controller){parent.block(false);handle.remove();mask.remove();page.remove();}}};
}
function registerMount(){if(!F||['candidate','mutate','verify','projection','context'].some(k=>typeof F[k]!=='function'))throw Error('家庭模型未完整加载');const intake=document.body.dataset.page==='intake',legacy=new URLSearchParams(root.location?.search||'').get('legacy')==='1';if(intake){if(document.head&&!document.querySelector('link[data-family-glass]')){const style=document.createElement('link');style.rel='stylesheet';style.href='family.css';style.setAttribute('data-family-glass','19');document.head.append(style);}if(!legacy)root.NutriFamilyDrawer=Object.freeze({attach});return;}return mount();}
E.register('family-ui',{buildId:'registration-web-v3-c1',mount:registerMount});})(window);
